const parts = msg.topic.split('/');
const buildingId = parts[1] || 'B1';
const p = msg.payload || {};

let evt = null;

if (parts[2] === 'zone' && parts[4] === 'badge') {
    const zoneId = parts[3];
    const readerId = parts[5];
    evt = {
        event_type: 'BADGE_ACCESS',
        source_layer: 'PHYSICAL',
        severity_raw: 'INFO',
        zone_id: zoneId,
        device_id: readerId,
        user_id: p.user_id || null,
        payload: {
            kind: 'BADGE_ACCESS',
            badge_id: String(p.badge_id || 'unknown'),
            reader_device_id: readerId,
            access_result: String(p.access_result || 'GRANTED').toUpperCase(),
            door_id: p.door_id || null
        }
    };
} else if (parts[2] === 'zone' && parts[4] === 'door') {
    const zoneId = parts[3];
    const doorId = parts[5];
    const state = String(p.state || 'OPEN').toUpperCase();
    let etype = 'DOOR_OPENED';
    let sev = 'INFO';
    if (state === 'FORCED') { etype = 'DOOR_FORCED'; sev = 'ALERT'; }
    else if (state === 'CLOSED') { etype = 'DOOR_CLOSED'; }
    const payload = { kind: etype, door_id: doorId, state: state };
    if (state === 'FORCED') {
        payload.no_badge_window_seconds = parseFloat(p.no_badge_window_seconds || 10);
    } else if (state === 'CLOSED' && p.open_duration_seconds !== undefined) {
        payload.open_duration_seconds = parseFloat(p.open_duration_seconds);
    }
    evt = {
        event_type: etype,
        source_layer: 'PHYSICAL',
        severity_raw: sev,
        zone_id: zoneId,
        device_id: doorId,
        user_id: null,
        payload: payload
    };
} else if (parts[2] === 'zone' && parts[4] === 'motion') {
    const zoneId = parts[3];
    const detectorId = parts[5];
    evt = {
        event_type: 'MOTION_DETECTED',
        source_layer: 'PHYSICAL',
        severity_raw: 'INFO',
        zone_id: zoneId,
        device_id: detectorId,
        user_id: null,
        payload: {
            kind: 'MOTION_DETECTED',
            detector_device_id: detectorId,
            entity_count: parseInt(p.entity_count) || 1
        }
    };
} else if (parts[2] === 'network' && parts[3] === 'alert') {
    evt = {
        event_type: 'NETWORK_ANOMALY',
        source_layer: 'CYBER',
        severity_raw: 'ALERT',
        zone_id: p.zone_id || 'UNKNOWN',
        device_id: p.device_id || 'unknown',
        user_id: null,
        payload: {
            kind: 'NETWORK_ANOMALY',
            anomaly_label: String(p.anomaly_label || 'UNKNOWN').toUpperCase(),
            src_ip: String(p.src_ip || '0.0.0.0'),
            severity_hint: parseFloat(p.severity_hint) || 0.7
        }
    };
} else if (parts[2] === 'network' && parts[3] === 'flow') {
    evt = {
        event_type: 'NETWORK_FLOW',
        source_layer: 'CYBER',
        severity_raw: 'INFO',
        zone_id: p.zone_id || 'UNKNOWN',
        device_id: p.device_id || 'unknown',
        user_id: null,
        payload: {
            kind: 'NETWORK_FLOW',
            src_ip: String(p.src_ip || '0.0.0.0'),
            dst_ip: String(p.dst_ip || '0.0.0.0'),
            bytes_out: parseInt(p.bytes_out || p.bytes_sent) || 0,
            bytes_in: parseInt(p.bytes_in || p.bytes_received) || 0,
            distinct_dst_ports: parseInt(p.distinct_dst_ports) || 1,
            window_seconds: parseFloat(p.window_seconds) || 60.0
        }
    };
} else {
    node.warn('unknown topic shape: ' + msg.topic);
    return null;
}

const now = new Date().toISOString();
const ts = p.timestamp || now;

msg.payload = {
    event_id: crypto.randomUUID(),
    schema_version: '1.0.0',
    event_type: evt.event_type,
    source_layer: evt.source_layer,
    timestamp: ts,
    ingestion_timestamp: now,
    building_id: buildingId,
    zone_id: evt.zone_id,
    device_id: evt.device_id,
    user_id: evt.user_id,
    severity_raw: evt.severity_raw,
    payload: evt.payload,
    correlated_events: []
};
return msg;

const producer = context.get('producer');
if (!producer) {
    node.warn('kafka producer not connected yet');
    return null;
}
try {
    await producer.send({
        topic: 'events.raw',
        messages: [{ value: JSON.stringify(msg.payload) }]
    });
    node.status({ fill: 'green', shape: 'dot', text: 'sent ' + msg.payload.event_type });
} catch (err) {
    node.warn('kafka send failed: ' + err.message);
    node.status({ fill: 'red', shape: 'ring', text: err.message });
}
return null;

initialize:
const { Kafka } = kafkajs;
const brokers = (env.get('NR_KAFKA_BROKERS') || 'kafka:9092').split(',');
const kafka = new Kafka({ clientId: 'nodered-middleware', brokers: brokers });
const producer = kafka.producer({ allowAutoTopicCreation: false });
await producer.connect();
context.set('producer', producer);
node.log('kafka producer connected to ' + brokers.join(','));
node.status({ fill: 'blue', shape: 'dot', text: 'connected' });

finalize:
const producer = context.get('producer');
context.set('producer', null);
if (producer) {
    producer.disconnect().catch(function () {});
}
